// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_PT: NistCatalogFamily = {"code":"PT","name":"Personally Identifiable Information Processing and Transparency","controls":[{"id":"PT-1","oscal_id":"pt-1","family":"PT","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> personally identifiable information processing and transparency policy that:\n    <organization-defined parameter> personally identifiable information processing and transparency policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the personally identifiable information processing and transparency policy and the associated personally identifiable information processing and transparency controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the personally identifiable information processing and transparency policy and procedures; and\nc. Review and update the current personally identifiable information processing and transparency:\n  Review and update the current personally identifiable information processing and transparency:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Personally identifiable information processing and transparency policy and procedures address the controls in the PT family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of personally identifiable information processing and transparency policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to personally identifiable information processing and transparency policy and procedures include assessment or audit findings, breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"pt-1_prm_1","label":"organization-defined personnel or roles"},{"id":"pt-01_odp.01","label":"personnel or roles"},{"id":"pt-01_odp.02","label":"personnel or roles"},{"id":"pt-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"pt-01_odp.04","label":"official"},{"id":"pt-01_odp.05","label":"frequency"},{"id":"pt-01_odp.06","label":"events"},{"id":"pt-01_odp.07","label":"frequency"},{"id":"pt-01_odp.08","label":"events"}],"objectives":[{"id":"pt-1_obj.a-1","label":"PT-01a.[01]","text":"a personally identifiable information processing and transparency policy is developed and documented;"},{"id":"pt-1_obj.a-2","label":"PT-01a.[02]","text":"the personally identifiable information processing and transparency policy is disseminated to {{ insert: param, pt-01_odp.01 }};"},{"id":"pt-1_obj.a-3","label":"PT-01a.[03]","text":"personally identifiable information processing and transparency procedures to facilitate the implementation of the personally identifiable information processing and transparency policy and associated personally identifiable information processing and transparency controls are developed and documented;"},{"id":"pt-1_obj.a-4","label":"PT-01a.[04]","text":"the personally identifiable information processing and transparency procedures are disseminated to {{ insert: param, pt-01_odp.02 }};"},{"id":"pt-1_obj.a.1.a-1","label":"PT-01a.01(a)[01]","text":"the {{ insert: param, pt-01_odp.03 }} personally identifiable information processing and transparency policy addresses purpose;"},{"id":"pt-1_obj.a.1.a-2","label":"PT-01a.01(a)[02]","text":"the {{ insert: param, pt-01_odp.03 }} personally identifiable information processing and transparency policy addresses scope;"},{"id":"pt-1_obj.a.1.a-3","label":"PT-01a.01(a)[03]","text":"the {{ insert: param, pt-01_odp.03 }} personally identifiable information processing and transparency policy addresses roles;"},{"id":"pt-1_obj.a.1.a-4","label":"PT-01a.01(a)[04]","text":"the {{ insert: param, pt-01_odp.03 }} personally identifiable information processing and transparency policy addresses responsibilities;"},{"id":"pt-1_obj.a.1.a-5","label":"PT-01a.01(a)[05]","text":"the {{ insert: param, pt-01_odp.03 }} personally identifiable information processing and transparency policy addresses management commitment;"},{"id":"pt-1_obj.a.1.a-6","label":"PT-01a.01(a)[06]","text":"the {{ insert: param, pt-01_odp.03 }} personally identifiable information processing and transparency policy addresses coordination among organizational entities;"},{"id":"pt-1_obj.a.1.a-7","label":"PT-01a.01(a)[07]","text":"the {{ insert: param, pt-01_odp.03 }} personally identifiable information processing and transparency policy addresses compliance;"},{"id":"pt-1_obj.a.1.b","label":"PT-01a.01(b)","text":"the {{ insert: param, pt-01_odp.03 }} personally identifiable information processing and transparency policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"pt-1_obj.b","label":"PT-01b.","text":"the {{ insert: param, pt-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the personally identifiable information processing and transparency policy and procedures;"},{"id":"pt-1_obj.c.1-1","label":"PT-01c.01[01]","text":"the current personally identifiable information processing and transparency policy is reviewed and updated {{ insert: param, pt-01_odp.05 }};"},{"id":"pt-1_obj.c.1-2","label":"PT-01c.01[02]","text":"the current personally identifiable information processing and transparency policy is reviewed and updated following {{ insert: param, pt-01_odp.06 }};"},{"id":"pt-1_obj.c.2-1","label":"PT-01c.02[01]","text":"the current personally identifiable information processing and transparency procedures are reviewed and updated {{ insert: param, pt-01_odp.07 }};"},{"id":"pt-1_obj.c.2-2","label":"PT-01c.02[02]","text":"the current personally identifiable information processing and transparency procedures are reviewed and updated following {{ insert: param, pt-01_odp.08 }}."}],"methods":[{"method":"examine","label":"PT-01-Examine"},{"method":"interview","label":"PT-01-Interview"}],"references":[{"title":"OMB A-130"}]},{"id":"PT-2","oscal_id":"pt-2","family":"PT","title":"Authority to Process Personally Identifiable Information","statement":"a. Determine and document the <authority> that permits the <processing> of personally identifiable information; and\nb. Restrict the <processing> of personally identifiable information to only that which is authorized.","supplemental_guidance":"The processing of personally identifiable information is an operation or set of operations that the information system or organization performs with respect to personally identifiable information across the information life cycle. Processing includes but is not limited to creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposal. Processing operations also include logging, generation, and transformation, as well as analysis techniques, such as data mining.\n\nOrganizations may be subject to laws, executive orders, directives, regulations, or policies that establish the organization’s authority and thereby limit certain types of processing of personally identifiable information or establish other requirements related to the processing. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such authority, particularly if the organization is subject to multiple jurisdictions or sources of authority. For organizations whose processing is not determined according to legal authorities, the organization’s policies and determinations govern how they process personally identifiable information. While processing of personally identifiable information may be legally permissible, privacy risks may still arise. Privacy risk assessments can identify the privacy risks associated with the authorized processing of personally identifiable information and support solutions to manage such risks.\n\nOrganizations consider applicable requirements and organizational policies to determine how to document this authority. For federal agencies, the authority to process personally identifiable information is documented in privacy policies and notices, system of records notices, privacy impact assessments, [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) statements, computer matching agreements and notices, contracts, information sharing agreements, memoranda of understanding, and other documentation.\n\nOrganizations take steps to ensure that personally identifiable information is only processed for authorized purposes, including training organizational personnel on the authorized processing of personally identifiable information and monitoring and auditing organizational use of personally identifiable information.","implementation_level":"organization","parameters":[{"id":"pt-02_odp.01","label":"authority"},{"id":"pt-02_odp.02","label":"processing"},{"id":"pt-02_odp.03","label":"processing"}],"objectives":[{"id":"pt-2_obj.a","label":"PT-02a.","text":"the {{ insert: param, pt-02_odp.01 }} that permits the {{ insert: param, pt-02_odp.02 }} of personally identifiable information is determined and documented;"},{"id":"pt-2_obj.b","label":"PT-02b.","text":"the {{ insert: param, pt-02_odp.03 }} of personally identifiable information is restricted to only that which is authorized."}],"methods":[{"method":"examine","label":"PT-02-Examine"},{"method":"interview","label":"PT-02-Interview"},{"method":"test","label":"PT-02-Test"}],"references":[{"title":"PRIVACT"},{"title":"OMB A-130"},{"title":"IR 8112"}],"related_controls":["AC-2","AC-3","CM-13","IR-9","PM-9","PM-24","PT-1","PT-3","PT-5","PT-6","RA-3","RA-8","SI-12","SI-18"],"enhancements":[{"id":"PT-2(1)","oscal_id":"pt-2.1","family":"PT","title":"Data Tagging","statement":"Attach data tags containing <authorized processing> to <elements of personally identifiable information>.","supplemental_guidance":"Data tags support the tracking and enforcement of authorized processing by conveying the types of processing that are authorized along with the relevant elements of personally identifiable information throughout the system. Data tags may also support the use of automated tools.","implementation_level":"system","parameters":[{"id":"pt-02.01_odp.01","label":"authorized processing"},{"id":"pt-02.01_odp.02","label":"elements of personally identifiable information"}],"methods":[{"method":"examine","label":"PT-02(01)-Examine"},{"method":"interview","label":"PT-02(01)-Interview"},{"method":"test","label":"PT-02(01)-Test"}],"related_controls":["AC-16","CA-6","CM-12","PM-5","PM-22","PT-4","SC-16","SC-43","SI-10","SI-15","SI-19"],"is_enhancement":true,"parent_id":"PT-2"},{"id":"PT-2(2)","oscal_id":"pt-2.2","family":"PT","title":"Automation","statement":"Manage enforcement of the authorized processing of personally identifiable information using <automated mechanisms>.","supplemental_guidance":"Automated mechanisms augment verification that only authorized processing is occurring.","implementation_level":"organization","parameters":[{"id":"pt-02.02_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"PT-02(02)-Examine"},{"method":"interview","label":"PT-02(02)-Interview"},{"method":"test","label":"PT-02(02)-Test"}],"related_controls":["CA-6","CM-12","PM-5","PM-22","PT-4","SC-16","SC-43","SI-10","SI-15","SI-19"],"is_enhancement":true,"parent_id":"PT-2"}]},{"id":"PT-3","oscal_id":"pt-3","family":"PT","title":"Personally Identifiable Information Processing Purposes","statement":"a. Identify and document the <purpose(s)> for processing personally identifiable information;\nb. Describe the purpose(s) in the public privacy notices and policies of the organization;\nc. Restrict the <processing> of personally identifiable information to only that which is compatible with the identified purpose(s); and\nd. Monitor changes in processing personally identifiable information and implement <mechanisms> to ensure that any changes are made in accordance with <requirements>.","supplemental_guidance":"Identifying and documenting the purpose for processing provides organizations with a basis for understanding why personally identifiable information may be processed. The term \"process\" includes every step of the information life cycle, including creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposal. Identifying and documenting the purpose of processing is a prerequisite to enabling owners and operators of the system and individuals whose information is processed by the system to understand how the information will be processed. This enables individuals to make informed decisions about their engagement with information systems and organizations and to manage their privacy interests. Once the specific processing purpose has been identified, the purpose is described in the organization’s privacy notices, policies, and any related privacy compliance documentation, including privacy impact assessments, system of records notices, [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) statements, computer matching notices, and other applicable Federal Register notices.\n\nOrganizations take steps to help ensure that personally identifiable information is processed only for identified purposes, including training organizational personnel and monitoring and auditing organizational processing of personally identifiable information.\n\nOrganizations monitor for changes in personally identifiable information processing. Organizational personnel consult with the senior agency official for privacy and legal counsel to ensure that any new purposes that arise from changes in processing are compatible with the purpose for which the information was collected, or if the new purpose is not compatible, implement mechanisms in accordance with defined requirements to allow for the new processing, if appropriate. Mechanisms may include obtaining consent from individuals, revising privacy policies, or other measures to manage privacy risks that arise from changes in personally identifiable information processing purposes.","implementation_level":"organization","parameters":[{"id":"pt-03_odp.01","label":"purpose(s)"},{"id":"pt-03_odp.02","label":"processing"},{"id":"pt-03_odp.03","label":"mechanisms"},{"id":"pt-03_odp.04","label":"requirements"}],"objectives":[{"id":"pt-3_obj.a","label":"PT-03a.","text":"the {{ insert: param, pt-03_odp.01 }} for processing personally identifiable information is/are identified and documented;"},{"id":"pt-3_obj.b-1","label":"PT-03b.[01]","text":"the purpose(s) is/are described in the public privacy notices of the organization;"},{"id":"pt-3_obj.b-2","label":"PT-03b.[02]","text":"the purpose(s) is/are described in the policies of the organization;"},{"id":"pt-3_obj.c","label":"PT-03c.","text":"the {{ insert: param, pt-03_odp.02 }} of personally identifiable information are restricted to only that which is compatible with the identified purpose(s);"},{"id":"pt-3_obj.d-1","label":"PT-03d.[01]","text":"changes in the processing of personally identifiable information are monitored;"},{"id":"pt-3_obj.d-2","label":"PT-03d.[02]","text":"{{ insert: param, pt-03_odp.03 }} are implemented to ensure that any changes are made in accordance with {{ insert: param, pt-03_odp.04 }}."}],"methods":[{"method":"examine","label":"PT-03-Examine"},{"method":"interview","label":"PT-03-Interview"},{"method":"test","label":"PT-03-Test"}],"references":[{"title":"PRIVACT"},{"title":"OMB A-130"},{"title":"IR 8112"}],"related_controls":["AC-2","AC-3","AT-3","CM-13","IR-9","PM-9","PM-25","PT-2","PT-5","PT-6","PT-7","RA-8","SC-43","SI-12","SI-18"],"enhancements":[{"id":"PT-3(1)","oscal_id":"pt-3.1","family":"PT","title":"Data Tagging","statement":"Attach data tags containing the following purposes to <elements of personally identifiable information>: <processing purposes>.","supplemental_guidance":"Data tags support the tracking of processing purposes by conveying the purposes along with the relevant elements of personally identifiable information throughout the system. By conveying the processing purposes in a data tag along with the personally identifiable information as the information transits a system, a system owner or operator can identify whether a change in processing would be compatible with the identified and documented purposes. Data tags may also support the use of automated tools.","implementation_level":"system","parameters":[{"id":"pt-03.01_odp.01","label":"processing purposes"},{"id":"pt-03.01_odp.02","label":"elements of personally identifiable information"}],"methods":[{"method":"examine","label":"PT-03(01)-Examine"},{"method":"interview","label":"PT-03(01)-Interview"},{"method":"test","label":"PT-03(01)-Test"}],"related_controls":["CA-6","CM-12","PM-5","PM-22","SC-16","SC-43","SI-10","SI-15","SI-19"],"is_enhancement":true,"parent_id":"PT-3"},{"id":"PT-3(2)","oscal_id":"pt-3.2","family":"PT","title":"Automation","statement":"Track processing purposes of personally identifiable information using <automated mechanisms>.","supplemental_guidance":"Automated mechanisms augment tracking of the processing purposes.","implementation_level":"organization","parameters":[{"id":"pt-03.02_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"PT-03(02)-Examine"},{"method":"interview","label":"PT-03(02)-Interview"},{"method":"test","label":"PT-03(02)-Test"}],"related_controls":["CA-6","CM-12","PM-5","PM-22","SC-16","SC-43","SI-10","SI-15","SI-19"],"is_enhancement":true,"parent_id":"PT-3"}]},{"id":"PT-4","oscal_id":"pt-4","family":"PT","title":"Consent","statement":"Implement <tools or mechanisms> for individuals to consent to the processing of their personally identifiable information prior to its collection that facilitate individuals’ informed decision-making.","supplemental_guidance":"Consent allows individuals to participate in making decisions about the processing of their information and transfers some of the risk that arises from the processing of personally identifiable information from the organization to an individual. Consent may be required by applicable laws, executive orders, directives, regulations, policies, standards, or guidelines. Otherwise, when selecting consent as a control, organizations consider whether individuals can be reasonably expected to understand and accept the privacy risks that arise from their authorization. Organizations consider whether other controls may more effectively mitigate privacy risk either alone or in conjunction with consent. Organizations also consider any demographic or contextual factors that may influence the understanding or behavior of individuals with respect to the processing carried out by the system or organization. When soliciting consent from individuals, organizations consider the appropriate mechanism for obtaining consent, including the type of consent (e.g., opt-in, opt-out), how to properly authenticate and identity proof individuals and how to obtain consent through electronic means. In addition, organizations consider providing a mechanism for individuals to revoke consent once it has been provided, as appropriate. Finally, organizations consider usability factors to help individuals understand the risks being accepted when providing consent, including the use of plain language and avoiding technical jargon.","implementation_level":"organization","parameters":[{"id":"pt-04_odp","label":"tools or mechanisms"}],"methods":[{"method":"examine","label":"PT-04-Examine"},{"method":"interview","label":"PT-04-Interview"},{"method":"test","label":"PT-04-Test"}],"references":[{"title":"PRIVACT"},{"title":"OMB A-130"},{"title":"SP 800-63-3"}],"related_controls":["AC-16","PT-2","PT-5"],"enhancements":[{"id":"PT-4(1)","oscal_id":"pt-4.1","family":"PT","title":"Tailored Consent","statement":"Provide <mechanisms> to allow individuals to tailor processing permissions to selected elements of personally identifiable information.","supplemental_guidance":"While some processing may be necessary for the basic functionality of the product or service, other processing may not. In these circumstances, organizations allow individuals to select how specific personally identifiable information elements may be processed. More tailored consent may help reduce privacy risk, increase individual satisfaction, and avoid adverse behaviors, such as abandonment of the product or service.","implementation_level":"organization","parameters":[{"id":"pt-04.01_odp","label":"mechanisms"}],"methods":[{"method":"examine","label":"PT-04(01)-Examine"},{"method":"interview","label":"PT-04(01)-Interview"},{"method":"test","label":"PT-04(01)-Test"}],"related_controls":["PT-2"],"is_enhancement":true,"parent_id":"PT-4"},{"id":"PT-4(2)","oscal_id":"pt-4.2","family":"PT","title":"Just-in-time Consent","statement":"Present <consent mechanisms> to individuals at <frequency> and in conjunction with <personally identifiable information processing>.","supplemental_guidance":"Just-in-time consent enables individuals to participate in how their personally identifiable information is being processed at the time or in conjunction with specific types of data processing when such participation may be most useful to the individual. Individual assumptions about how personally identifiable information is being processed might not be accurate or reliable if time has passed since the individual last gave consent or the type of processing creates significant privacy risk. Organizations use discretion to determine when to use just-in-time consent and may use supporting information on demographics, focus groups, or surveys to learn more about individuals’ privacy interests and concerns.","implementation_level":"organization","parameters":[{"id":"pt-04.02_odp.01","label":"consent mechanisms"},{"id":"pt-04.02_odp.02","label":"frequency"},{"id":"pt-04.02_odp.03","label":"personally identifiable information processing"}],"methods":[{"method":"examine","label":"PT-04(02)-Examine"},{"method":"interview","label":"PT-04(02)-Interview"},{"method":"test","label":"PT-04(02)-Test"}],"related_controls":["PT-2"],"is_enhancement":true,"parent_id":"PT-4"},{"id":"PT-4(3)","oscal_id":"pt-4.3","family":"PT","title":"Revocation","statement":"Implement <tools or mechanisms> for individuals to revoke consent to the processing of their personally identifiable information.","supplemental_guidance":"Revocation of consent enables individuals to exercise control over their initial consent decision when circumstances change. Organizations consider usability factors in enabling easy-to-use revocation capabilities.","implementation_level":"organization","parameters":[{"id":"pt-04.03_odp","label":"tools or mechanisms"}],"methods":[{"method":"examine","label":"PT-04(03)-Examine"},{"method":"interview","label":"PT-04(03)-Interview"},{"method":"test","label":"PT-04(03)-Test"}],"related_controls":["PT-2"],"is_enhancement":true,"parent_id":"PT-4"}]},{"id":"PT-5","oscal_id":"pt-5","family":"PT","title":"Privacy Notice","statement":"Provide notice to individuals about the processing of personally identifiable information that:\na. Is available to individuals upon first interacting with an organization, and subsequently at <frequency>;\nb. Is clear and easy-to-understand, expressing information about personally identifiable information processing in plain language;\nc. Identifies the authority that authorizes the processing of personally identifiable information;\nd. Identifies the purposes for which personally identifiable information is to be processed; and\ne. Includes <information>.","supplemental_guidance":"Privacy notices help inform individuals about how their personally identifiable information is being processed by the system or organization. Organizations use privacy notices to inform individuals about how, under what authority, and for what purpose their personally identifiable information is processed, as well as other information such as choices individuals might have with respect to that processing and other parties with whom information is shared. Laws, executive orders, directives, regulations, or policies may require that privacy notices include specific elements or be provided in specific formats. Federal agency personnel consult with the senior agency official for privacy and legal counsel regarding when and where to provide privacy notices, as well as elements to include in privacy notices and required formats. In circumstances where laws or government-wide policies do not require privacy notices, organizational policies and determinations may require privacy notices and may serve as a source of the elements to include in privacy notices.\n\nPrivacy risk assessments identify the privacy risks associated with the processing of personally identifiable information and may help organizations determine appropriate elements to include in a privacy notice to manage such risks. To help individuals understand how their information is being processed, organizations write materials in plain language and avoid technical jargon.","implementation_level":"organization","parameters":[{"id":"pt-05_odp.01","label":"frequency"},{"id":"pt-05_odp.02","label":"information"}],"objectives":[{"id":"pt-5_obj.a-1","label":"PT-05a.[01]","text":"a notice to individuals about the processing of personally identifiable information is provided such that the notice is available to individuals upon first interacting with an organization;"},{"id":"pt-5_obj.a-2","label":"PT-05a.[02]","text":"a notice to individuals about the processing of personally identifiable information is provided such that the notice is subsequently available to individuals {{ insert: param, pt-05_odp.01 }};"},{"id":"pt-5_obj.b","label":"PT-05b.","text":"a notice to individuals about the processing of personally identifiable information is provided that is clear, easy-to-understand, and expresses information about personally identifiable information processing in plain language;"},{"id":"pt-5_obj.c","label":"PT-05c.","text":"a notice to individuals about the processing of personally identifiable information that identifies the authority that authorizes the processing of personally identifiable information is provided;"},{"id":"pt-5_obj.d","label":"PT-05d.","text":"a notice to individuals about the processing of personally identifiable information that identifies the purpose for which personally identifiable information is to be processed is provided;"},{"id":"pt-5_obj.e","label":"PT-05e.","text":"a notice to individuals about the processing of personally identifiable information which includes {{ insert: param, pt-05_odp.02 }} is provided."}],"methods":[{"method":"examine","label":"PT-05-Examine"},{"method":"interview","label":"PT-05-Interview"},{"method":"test","label":"PT-05-Test"}],"references":[{"title":"PRIVACT"},{"title":"OMB A-130"},{"title":"OMB A-108"}],"related_controls":["PM-20","PM-22","PT-2","PT-3","PT-4","PT-7","RA-3","SC-42","SI-18"],"enhancements":[{"id":"PT-5(1)","oscal_id":"pt-5.1","family":"PT","title":"Just-in-time Notice","statement":"Present notice of personally identifiable information processing to individuals at a time and location where the individual provides personally identifiable information or in conjunction with a data action, or <frequency>.","supplemental_guidance":"Just-in-time notices inform individuals of how organizations process their personally identifiable information at a time when such notices may be most useful to the individuals. Individual assumptions about how personally identifiable information will be processed might not be accurate or reliable if time has passed since the organization last presented notice or the circumstances under which the individual was last provided notice have changed. A just-in-time notice can explain data actions that organizations have identified as potentially giving rise to greater privacy risk for individuals. Organizations can use a just-in-time notice to update or remind individuals about specific data actions as they occur or highlight specific changes that occurred since last presenting notice. A just-in-time notice can be used in conjunction with just-in-time consent to explain what will occur if consent is declined. Organizations use discretion to determine when to use a just-in-time notice and may use supporting information on user demographics, focus groups, or surveys to learn about users’ privacy interests and concerns.","implementation_level":"organization","parameters":[{"id":"pt-05.01_odp","label":"frequency"}],"methods":[{"method":"examine","label":"PT-05(01)-Examine"},{"method":"interview","label":"PT-05(01)-Interview"},{"method":"test","label":"PT-05(01)-Test"}],"related_controls":["PM-21"],"is_enhancement":true,"parent_id":"PT-5"},{"id":"PT-5(2)","oscal_id":"pt-5.2","family":"PT","title":"Privacy Act Statements","statement":"Include Privacy Act statements on forms that collect information that will be maintained in a Privacy Act system of records, or provide Privacy Act statements on separate forms that can be retained by individuals.","supplemental_guidance":"If a federal agency asks individuals to supply information that will become part of a system of records, the agency is required to provide a [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) statement on the form used to collect the information or on a separate form that can be retained by the individual. The agency provides a [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) statement in such circumstances regardless of whether the information will be collected on a paper or electronic form, on a website, on a mobile application, over the telephone, or through some other medium. This requirement ensures that the individual is provided with sufficient information about the request for information to make an informed decision on whether or not to respond.\n\n[PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) statements provide formal notice to individuals of the authority that authorizes the solicitation of the information; whether providing the information is mandatory or voluntary; the principal purpose(s) for which the information is to be used; the published routine uses to which the information is subject; the effects on the individual, if any, of not providing all or any part of the information requested; and an appropriate citation and link to the relevant system of records notice. Federal agency personnel consult with the senior agency official for privacy and legal counsel regarding the notice provisions of the [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455).","implementation_level":"organization","methods":[{"method":"examine","label":"PT-05(02)-Examine"},{"method":"interview","label":"PT-05(02)-Interview"},{"method":"test","label":"PT-05(02)-Test"}],"related_controls":["PT-6"],"is_enhancement":true,"parent_id":"PT-5"}]},{"id":"PT-6","oscal_id":"pt-6","family":"PT","title":"System of Records Notice","statement":"For systems that process information that will be maintained in a Privacy Act system of records:\na. Draft system of records notices in accordance with OMB guidance and submit new and significantly modified system of records notices to the OMB and appropriate congressional committees for advance review;\nb. Publish system of records notices in the Federal Register; and\nc. Keep system of records notices accurate, up-to-date, and scoped in accordance with policy.","supplemental_guidance":"The [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) requires that federal agencies publish a system of records notice in the Federal Register upon the establishment and/or modification of a [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) system of records. As a general matter, a system of records notice is required when an agency maintains a group of any records under the control of the agency from which information is retrieved by the name of an individual or by some identifying number, symbol, or other identifier. The notice describes the existence and character of the system and identifies the system of records, the purpose(s) of the system, the authority for maintenance of the records, the categories of records maintained in the system, the categories of individuals about whom records are maintained, the routine uses to which the records are subject, and additional details about the system as described in [OMB A-108](#3671ff20-c17c-44d6-8a88-7de203fa74aa).","implementation_level":"organization","objectives":[{"id":"pt-6_obj.a-1","label":"PT-06a.[01]","text":"system of records notices are drafted in accordance with OMB guidance for systems that process information that will be maintained in a Privacy Act system of records;"},{"id":"pt-6_obj.a-2","label":"PT-06a.[02]","text":"new and significantly modified system of records notices are submitted to the OMB and appropriate congressional committees for advance review for systems that process information that will be maintained in a Privacy Act system of records;"},{"id":"pt-6_obj.b","label":"PT-06b.","text":"system of records notices are published in the Federal Register for systems that process information that will be maintained in a Privacy Act system of records;"},{"id":"pt-6_obj.c","label":"PT-06c.","text":"system of records notices are kept accurate, up-to-date, and scoped in accordance with policy for systems that process information that will be maintained in a Privacy Act system of records."}],"methods":[{"method":"examine","label":"PT-06-Examine"},{"method":"interview","label":"PT-06-Interview"},{"method":"test","label":"PT-06-Test"}],"references":[{"title":"PRIVACT"},{"title":"OMB A-108"}],"related_controls":["AC-3","PM-20","PT-2","PT-3","PT-5"],"enhancements":[{"id":"PT-6(1)","oscal_id":"pt-6.1","family":"PT","title":"Routine Uses","statement":"Review all routine uses published in the system of records notice at <frequency> to ensure continued accuracy, and to ensure that routine uses continue to be compatible with the purpose for which the information was collected.","supplemental_guidance":"A [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) routine use is a particular kind of disclosure of a record outside of the federal agency maintaining the system of records. A routine use is an exception to the [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) prohibition on the disclosure of a record in a system of records without the prior written consent of the individual to whom the record pertains. To qualify as a routine use, the disclosure must be for a purpose that is compatible with the purpose for which the information was originally collected. The [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) requires agencies to describe each routine use of the records maintained in the system of records, including the categories of users of the records and the purpose of the use. Agencies may only establish routine uses by explicitly publishing them in the relevant system of records notice.","implementation_level":"organization","parameters":[{"id":"pt-06.01_odp","label":"frequency"}],"methods":[{"method":"examine","label":"PT-06(01)-Examine"},{"method":"interview","label":"PT-06(01)-Interview"},{"method":"test","label":"PT-06(01)-Test"}],"is_enhancement":true,"parent_id":"PT-6"},{"id":"PT-6(2)","oscal_id":"pt-6.2","family":"PT","title":"Exemption Rules","statement":"Review all Privacy Act exemptions claimed for the system of records at <frequency> to ensure they remain appropriate and necessary in accordance with law, that they have been promulgated as regulations, and that they are accurately described in the system of records notice.","supplemental_guidance":"The [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) includes two sets of provisions that allow federal agencies to claim exemptions from certain requirements in the statute. In certain circumstances, these provisions allow agencies to promulgate regulations to exempt a system of records from select provisions of the [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) . At a minimum, organizations’ [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) exemption regulations include the specific name(s) of any system(s) of records that will be exempt, the specific provisions of the [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) from which the system(s) of records is to be exempted, the reasons for the exemption, and an explanation for why the exemption is both necessary and appropriate.","implementation_level":"organization","parameters":[{"id":"pt-06.02_odp","label":"frequency"}],"objectives":[{"id":"pt-6.2_obj-1","label":"PT-06(02)[01]","text":"all Privacy Act exemptions claimed for the system of records are reviewed {{ insert: param, pt-06.02_odp }} to ensure that they remain appropriate and necessary in accordance with law;"},{"id":"pt-6.2_obj-2","label":"PT-06(02)[02]","text":"all Privacy Act exemptions claimed for the system of records are reviewed {{ insert: param, pt-06.02_odp }} to ensure that they have been promulgated as regulations;"},{"id":"pt-6.2_obj-3","label":"PT-06(02)[03]","text":"all Privacy Act exemptions claimed for the system of records are reviewed {{ insert: param, pt-06.02_odp }} to ensure that they are accurately described in the system of records notice."}],"methods":[{"method":"examine","label":"PT-06(02)-Examine"},{"method":"interview","label":"PT-06(02)-Interview"},{"method":"test","label":"PT-06(02)-Test"}],"is_enhancement":true,"parent_id":"PT-6"}]},{"id":"PT-7","oscal_id":"pt-7","family":"PT","title":"Specific Categories of Personally Identifiable Information","statement":"Apply <processing conditions> for specific categories of personally identifiable information.","supplemental_guidance":"Organizations apply any conditions or protections that may be necessary for specific categories of personally identifiable information. These conditions may be required by laws, executive orders, directives, regulations, policies, standards, or guidelines. The requirements may also come from the results of privacy risk assessments that factor in contextual changes that may result in an organizational determination that a particular category of personally identifiable information is particularly sensitive or raises particular privacy risks. Organizations consult with the senior agency official for privacy and legal counsel regarding any protections that may be necessary.","implementation_level":"organization","parameters":[{"id":"pt-07_odp","label":"processing conditions"}],"methods":[{"method":"examine","label":"PT-07-Examine"},{"method":"interview","label":"PT-07-Interview"},{"method":"test","label":"PT-07-Test"}],"references":[{"title":"PRIVACT"},{"title":"OMB A-130"},{"title":"OMB A-108"},{"title":"NARA CUI"}],"related_controls":["IR-9","PT-2","PT-3","RA-3"],"enhancements":[{"id":"PT-7(1)","oscal_id":"pt-7.1","family":"PT","title":"Social Security Numbers","statement":"When a system processes Social Security numbers:\n(a) Eliminate unnecessary collection, maintenance, and use of Social Security numbers, and explore alternatives to their use as a personal identifier;\n(b) Do not deny any individual any right, benefit, or privilege provided by law because of such individual’s refusal to disclose his or her Social Security number; and\n(c) Inform any individual who is asked to disclose his or her Social Security number whether that disclosure is mandatory or voluntary, by what statutory or other authority such number is solicited, and what uses will be made of it.","supplemental_guidance":"Federal law and policy establish specific requirements for organizations’ processing of Social Security numbers. Organizations take steps to eliminate unnecessary uses of Social Security numbers and other sensitive information and observe any particular requirements that apply.","implementation_level":"organization","objectives":[{"id":"pt-7.1_obj.a-1","label":"PT-07(01)(a)[01]","text":"when a system processes Social Security numbers, the unnecessary collection, maintenance, and use of Social Security numbers are eliminated;"},{"id":"pt-7.1_obj.a-2","label":"PT-07(01)(a)[02]","text":"when a system processes Social Security numbers, alternatives to the use of Social Security Numbers as a personal identifier are explored;"},{"id":"pt-7.1_obj.b","label":"PT-07(01)(b)","text":"when a system processes Social Security numbers, individual rights, benefits, or privileges provided by law are not denied because of an individual’s refusal to disclose their Social Security number;"},{"id":"pt-7.1_obj.c-1","label":"PT-07(01)(c)[01]","text":"when a system processes Social Security numbers, any individual who is asked to disclose their Social Security number is informed whether that disclosure is mandatory or voluntary, by what statutory or other authority such number is solicited, and what uses will be made of it;"},{"id":"pt-7.1_obj.c-2","label":"PT-07(01)(c)[02]","text":"when a system processes Social Security numbers, any individual who is asked to disclose their Social Security number is informed by what statutory or other authority the number is solicited;"},{"id":"pt-7.1_obj.c-3","label":"PT-07(01)(c)[03]","text":"when a system processes Social Security numbers, any individual who is asked to disclose their Social Security number is informed what uses will be made of it."}],"methods":[{"method":"examine","label":"PT-07(01)-Examine"},{"method":"interview","label":"PT-07(01)-Interview"},{"method":"test","label":"PT-07(01)-Test"}],"related_controls":["IA-4"],"is_enhancement":true,"parent_id":"PT-7"},{"id":"PT-7(2)","oscal_id":"pt-7.2","family":"PT","title":"First Amendment Information","statement":"Prohibit the processing of information describing how any individual exercises rights guaranteed by the First Amendment unless expressly authorized by statute or by the individual or unless pertinent to and within the scope of an authorized law enforcement activity.","supplemental_guidance":"The [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) limits agencies’ ability to process information that describes how individuals exercise rights guaranteed by the First Amendment. Organizations consult with the senior agency official for privacy and legal counsel regarding these requirements.","implementation_level":"organization","methods":[{"method":"examine","label":"PT-07(02)-Examine"},{"method":"interview","label":"PT-07(02)-Interview"},{"method":"test","label":"PT-07(02)-Test"}],"is_enhancement":true,"parent_id":"PT-7"}]},{"id":"PT-8","oscal_id":"pt-8","family":"PT","title":"Computer Matching Requirements","statement":"When a system or organization processes information for the purpose of conducting a matching program:\na. Obtain approval from the Data Integrity Board to conduct the matching program;\nb. Develop and enter into a computer matching agreement;\nc. Publish a matching notice in the Federal Register;\nd. Independently verify the information produced by the matching program before taking adverse action against an individual, if required; and\ne. Provide individuals with notice and an opportunity to contest the findings before taking adverse action against an individual.","supplemental_guidance":"The [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) establishes requirements for federal and non-federal agencies if they engage in a matching program. In general, a matching program is a computerized comparison of records from two or more automated [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) systems of records or an automated system of records and automated records maintained by a non-federal agency (or agent thereof). A matching program either pertains to federal benefit programs or federal personnel or payroll records. A federal benefit match is performed to determine or verify eligibility for payments under federal benefit programs or to recoup payments or delinquent debts under federal benefit programs. A matching program involves not just the matching activity itself but also the investigative follow-up and ultimate action, if any.","implementation_level":"organization","objectives":[{"id":"pt-8_obj.a","label":"PT-08a.","text":"approval to conduct the matching program is obtained from the Data Integrity Board when a system or organization processes information for the purpose of conducting a matching program;"},{"id":"pt-8_obj.b-1","label":"PT-08b.[01]","text":"a computer matching agreement is developed when a system or organization processes information for the purpose of conducting a matching program;"},{"id":"pt-8_obj.b-2","label":"PT-08b.[02]","text":"a computer matching agreement is entered into when a system or organization processes information for the purpose of conducting a matching program;"},{"id":"pt-8_obj.c","label":"PT-08c.","text":"a matching notice is published in the Federal Register when a system or organization processes information for the purpose of conducting a matching program;"},{"id":"pt-8_obj.d","label":"PT-08d.","text":"the information produced by the matching program is independently verified before taking adverse action against an individual, if required, when a system or organization processes information for the purpose of conducting a matching program;"},{"id":"pt-8_obj.e-1","label":"PT-08e.[01]","text":"individuals are provided with notice when a system or organization processes information for the purpose of conducting a matching program;"},{"id":"pt-8_obj.e-2","label":"PT-08e.[02]","text":"individuals are provided with an opportunity to contest the findings before adverse action is taken against them when a system or organization processes information for the purpose of conducting a matching program."}],"methods":[{"method":"examine","label":"PT-08-Examine"},{"method":"interview","label":"PT-08-Interview"},{"method":"test","label":"PT-08-Test"}],"references":[{"title":"PRIVACT"},{"title":"CMPPA"},{"title":"OMB A-130"},{"title":"OMB A-108"}],"related_controls":["PM-24"]}]};
